 58 │ 	 * place two literals in this file would have to be renamed together.
 59 │ 	 *
 60 │ 	 * <p>Package-private because it has to be: a class-level annotation cannot read a
 61 │ 	 * {@code private} member of its own class, qualified or not, so {@code @RequestMapping}
 62 │ 	 * above fixes the floor. The tests in this package can therefore see it, and the rule in
 63 │ 	 * this class's Javadoc that they write the path out instead is a convention rather than
 64 │ 	 * something the compiler enforces.
 65 │ 	 */
 66 │ 	static final String PATH = "/api/transfers";
 67 │ 
 68 │ 	private static final String SELF_TRANSFER_DETAIL =
