 70 │ 
 71 │ 	private static final String UNKNOWN_ACCOUNT_DETAIL = "No Account has that identifier.";
 72 │ 
 73 │ 	private static final String INSUFFICIENT_FUNDS_DETAIL =
 74 │ 			"The source Account's Available Balance does not cover this Transfer.";
 75 │ 
 76 │ 	private static final String CROSS_CURRENCY_DETAIL =
 77 │ 			"This service cannot yet convert between the two Accounts' Currencies.";
 78 │ 
 79 │ 	private static final String UNKNOWN_TRANSFER_DETAIL = "No Transfer has that identifier.";
 80 │ 
 81 │ 	private static final String REQUEST_IN_PROGRESS_DETAIL =
 82 │ 			"A request with this Idempotency Key is still being processed. Retry with the same key.";
 83 │ 
 84 │ 	private static final String IDEMPOTENCY_KEY_REUSED_DETAIL =
