103 │ 	TransferController(FundsReservation reservation, TransferLookup transfers,
104 │ 			IdempotentExecution requests, Clock clock) {
105 │ 		this.reservation = reservation;
106 │ 		this.transfers = transfers;
107 │ 		this.requests = requests;
108 │ 		this.clock = clock;
109 │ 	}
