291 │ 	}
292 │ 
293 │ 	/** The status the two idempotency refusals share, which is likewise all they share. */
294 │ 	private static ProblemDetail conflictOf(ProblemType type, String detail) {
295 │ 		return problemOf(HttpStatus.CONFLICT, type, detail);
